exec('import csv,os,math,pandas as pd,yfinance as yf\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\ncash_file="portfolio_cash.csv"; portfolio_file="virtual_portfolio.csv"; decision_file="intraday_decisions.csv"; now_paris=datetime.now(ZoneInfo("Europe/Paris")); now_utc=pd.Timestamp.now(tz="UTC")\ncash=list(csv.DictReader(open(cash_file,encoding="utf-8")))[0]; available=float(cash["available_cash_eur"]); positions=list(csv.DictReader(open(portfolio_file,encoding="utf-8"))); decisions=list(csv.DictReader(open(decision_file,encoding="utf-8"))) if os.path.exists(decision_file) else []; signals=list(csv.DictReader(open("signals_history.csv",encoding="utf-8"))) if os.path.exists("signals_history.csv") else []; score_map={(r["ticker"],r["date"]):int(r["score"]) for r in signals}\nfx=yf.download("EURUSD=X",period="1mo",progress=False,auto_adjust=True)["Close"].squeeze().dropna()\ndef fx_at(date):\n q=fx[fx.index.strftime("%Y-%m-%d")<=date]; return float(q.iloc[-1]) if len(q) else float(fx.iloc[-1])\ndef euro_fee(gross): return 1.0 if gross<=1000 else 2.55\ndef parse_time(value):\n ts=pd.Timestamp(value); return ts.tz_localize("Europe/Paris") if ts.tzinfo is None else ts\nfor p in positions:\n if p.get("status")!="OPEN": continue\n t=p["ticker"]; d=yf.download(t,period="1mo",interval="5m",progress=False,auto_adjust=True,prepost=False)\n if d.empty: print("PAS DE DONNEES",t); continue\n if hasattr(d.columns,"levels"): d.columns=d.columns.get_level_values(0)\n entry_ts=parse_time(p["decision_time"]); bars=d[d.index>entry_ts]; exit_price=None; exit_date=""; exit_reason=""\n for idx,row in bars.iterrows():\n  op=float(row["Open"]); hi=float(row["High"]); lo=float(row["Low"]); target=float(p["target_price"]); stop=float(p["stop_price"])\n  if op<=stop: exit_price=op; exit_reason="GAP SOUS STOP"\n  elif lo<=stop: exit_price=stop; exit_reason="STOP NET -2%"\n  elif op>=target: exit_price=op; exit_reason="GAP AU-DESSUS OBJECTIF"\n  elif hi>=target: exit_price=target; exit_reason="OBJECTIF NET +3%"\n  if exit_price is not None: exit_date=idx.strftime("%Y-%m-%d"); break\n if exit_price is not None:\n  qty=int(float(p["quantity"])); gross_local=qty*exit_price; rate=1.0 if p["currency"]=="EUR" else fx_at(exit_date); gross_eur=gross_local if p["currency"]=="EUR" else gross_local/rate; sell_fee=euro_fee(gross_eur) if p["currency"]=="EUR" else 10.5; net=gross_eur-sell_fee; realized=net-float(p["total_buy_cost_eur"]); available+=net; p.update({"status":"CLOSED","last_price":round(exit_price,4),"market_value_eur":0,"unrealized_pnl_eur":0,"exit_date":exit_date,"exit_price":round(exit_price,4),"gross_sell_value_local":round(gross_local,2),"gross_sell_value_eur":round(gross_eur,2),"sell_fee_eur":round(sell_fee,2),"net_sell_proceeds_eur":round(net,2),"realized_pnl_eur":round(realized,2),"exit_reason":exit_reason}); print("VENTE",t,"|",exit_reason,"| PnL",round(realized,2),"EUR")\n else:\n  last=float(d["Close"].dropna().iloc[-1]); date=d.index[-1].strftime("%Y-%m-%d"); rate=1.0 if p["currency"]=="EUR" else fx_at(date); gross=float(p["quantity"])*last if p["currency"]=="EUR" else float(p["quantity"])*last/rate; estimated_fee=euro_fee(gross) if p["currency"]=="EUR" else 10.5; unrealized=gross-estimated_fee-float(p["total_buy_cost_eur"]); p["last_price"]=round(last,4); p["market_value_eur"]=round(gross,2); p["unrealized_pnl_eur"]=round(unrealized,2); print("SUIVI",t,"| cours",round(last,2),p["currency"],"| PnL net",round(unrealized,2),"EUR")\nopen_tickers={p["ticker"] for p in positions if p.get("status")=="OPEN"}; open_count=len(open_tickers); used={(p["ticker"],p["signal_date"]) for p in positions}; candidates=[r for r in decisions if r.get("next_state")=="POSITION A OUVRIR" and r.get("decision") in ("ACHAT CONFIRME","ACHAT REACTIVE") and r["ticker"] not in open_tickers and (r["ticker"],r["signal_date"]) not in used]; candidates.sort(key=lambda r:(score_map.get((r["ticker"],r["signal_date"]),0),float(r.get("decision_volume") or 0)),reverse=True)\nfor r in candidates:\n decision_ts=parse_time(r["decision_time"]); age_minutes=(now_utc-decision_ts.tz_convert("UTC")).total_seconds()/60; decision_paris=decision_ts.tz_convert("Europe/Paris")\n if decision_paris.date()!=now_paris.date() or age_minutes<0 or age_minutes>10: print("DECISION PERIMEE",r["ticker"],"| age",round(age_minutes,1),"min | aucun achat"); continue\n max_positions=3 if float(cash.get("total_equity_eur") or 3000)<4000 else 4 if float(cash.get("total_equity_eur") or 3000)<5000 else 5\n if open_count>=max_positions: print("REFUSE",r["ticker"],"| maximum",max_positions,"positions"); continue\n t=r["ticker"]; price=float(r["decision_close"]); currency="EUR" if t.endswith((".PA",".AS")) else "USD"; rate=1.0 if currency=="EUR" else fx_at(r["session_date"]); unit_eur=price if currency=="EUR" else price/rate; budget=min(1000.0,available); base_fee=1.0 if currency=="EUR" else 10.5; qty=math.floor(max(0,budget-base_fee)/unit_eur)\n if qty==0 and 1000<unit_eur<2000 and available>=unit_eur+(2.55 if currency=="EUR" else 10.5): qty=1\n gross_local=qty*price; gross_eur=qty*unit_eur; buy_fee=(euro_fee(gross_eur) if currency=="EUR" else 10.5) if qty else 0; total_cost=gross_eur+buy_fee\n if qty<1 or total_cost>available+0.0001: print("NON EXECUTABLE",t,"| cash",round(available,2),"EUR | prix unitaire",round(unit_eur,2),"EUR"); continue\n estimated_target_fee=10.5 if currency=="USD" else euro_fee(total_cost*1.03); estimated_stop_fee=10.5 if currency=="USD" else euro_fee(total_cost*0.98); target_local=((total_cost*1.03+estimated_target_fee)/qty)*(rate if currency=="USD" else 1); stop_local=((total_cost*0.98+estimated_stop_fee)/qty)*(rate if currency=="USD" else 1)\n if stop_local>=price or target_local<=price: print("ORDRE REFUSE",t,"| frais incompatibles avec stop/objectif | entree",round(price,2),"stop",round(stop_local,2),"objectif",round(target_local,2)); continue\n available-=total_cost; positions.append({"ticker":t,"signal_date":r["signal_date"],"decision":r["decision"],"decision_time":r["decision_time"],"entry_date":r["session_date"],"entry_price":round(price,4),"currency":currency,"eurusd_entry":round(rate,6),"quantity":qty,"gross_buy_value_local":round(gross_local,2),"gross_buy_value_eur":round(gross_eur,2),"buy_fee_eur":round(buy_fee,2),"total_buy_cost_eur":round(total_cost,2),"target_price":round(target_local,4),"stop_price":round(stop_local,4),"status":"OPEN","last_price":round(price,4),"market_value_eur":round(gross_eur,2),"unrealized_pnl_eur":round(-buy_fee-estimated_stop_fee,2),"exit_date":"","exit_price":"","gross_sell_value_local":"","gross_sell_value_eur":"","sell_fee_eur":"","net_sell_proceeds_eur":"","realized_pnl_eur":"","exit_reason":""}); open_count+=1; open_tickers.add(t); print("ACHAT",t,"|",qty,"action(s) | cout",round(total_cost,2),"EUR | cash",round(available,2),"EUR")\nmarket_value=sum(float(p.get("market_value_eur") or 0) for p in positions if p.get("status")=="OPEN"); estimated_exit_fees=sum((euro_fee(float(p.get("market_value_eur") or 0)) if p.get("currency")=="EUR" else 10.5) for p in positions if p.get("status")=="OPEN"); invested=sum(float(p.get("total_buy_cost_eur") or 0) for p in positions if p.get("status")=="OPEN"); realized=sum(float(p.get("realized_pnl_eur") or 0) for p in positions if p.get("status")=="CLOSED"); unrealized=sum(float(p.get("unrealized_pnl_eur") or 0) for p in positions if p.get("status")=="OPEN"); fees=sum(float(p.get("buy_fee_eur") or 0)+float(p.get("sell_fee_eur") or 0) for p in positions); equity=available+market_value-estimated_exit_fees\nfields=["ticker","signal_date","decision","decision_time","entry_date","entry_price","currency","eurusd_entry","quantity","gross_buy_value_local","gross_buy_value_eur","buy_fee_eur","total_buy_cost_eur","target_price","stop_price","status","last_price","market_value_eur","unrealized_pnl_eur","exit_date","exit_price","gross_sell_value_local","gross_sell_value_eur","sell_fee_eur","net_sell_proceeds_eur","realized_pnl_eur","exit_reason"]\nwith open(portfolio_file,"w",newline="",encoding="utf-8") as q:\n w=csv.DictWriter(q,fieldnames=fields,extrasaction="ignore"); w.writeheader(); w.writerows(positions)\ncash_out={"initial_capital_eur":3000,"available_cash_eur":round(available,2),"invested_cost_eur":round(invested,2),"market_value_eur":round(market_value,2),"realized_pnl_eur":round(realized,2),"unrealized_pnl_eur":round(unrealized,2),"fees_paid_eur":round(fees,2),"total_equity_eur":round(equity,2)}\nwith open(cash_file,"w",newline="",encoding="utf-8") as q:\n w=csv.DictWriter(q,fieldnames=list(cash_out)); w.writeheader(); w.writerow(cash_out)\nprint("CAPITAL | cash",round(available,2),"EUR | positions",round(market_value,2),"EUR | equity nette",round(equity,2),"EUR")')
